UPDATE A SET A.USER_ID = U.USER_ID, A.DEPT_CD = U.DEPT_CD, A.JOB_DUTY_CD = U.JOB_DUTY_CD, A.NAME = U.USER_NAME, A.HP_NO = U.HP_NO, A.PASSWORD = U.PASSWORD, A.REMARKS = U.REMARKS FROM dbo.TAD_EMP A JOIN(
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.EMP_NO} AS EMP_NO, #{row.USER_ID} AS USER_ID, #{row.DEPT_CD} AS DEPT_CD, #{row.JOB_DUTY_CD} AS JOB_DUTY_CD, #{row.USER_NAME} AS USER_NAME, #{row.HP_NO} AS HP_NO, #{row.PASSWORD} AS PASSWORD, #{row.REMARKS} AS REMARKS
) AS U ON A.OFFICE_CODE = U.OFFICE_CODE AND A.EMP_NO = U.EMP_NO

UPDATE A SET A.PASSWD = U.PASSWD, A.USER_NAME = U.USER_NAME, A.REGI_DATE = U.REGI_DATE, A.USE_YN = U.USE_YN, A.HP_NO = U.HP_NO, A.STATUS = U.STATUS, A.REG_END_DATE = U.REG_END_DATE, A.DEPT_CD = U.DEPT_CD, A.JOB_DUTY_CD = U.JOB_DUTY_CD, A.ID_GBN = U.ID_GBN, A.REMARK = U.REMARK, A.EMP_NO = U.EMP_NO, A.GROUP_DTL_CD = U.GROUP_DTL_CD, A.EMAIL = U.EMAIL FROM dbo.TPM_USER A JOIN(
SELECT #{row.LOGINUSER_OFFICE_CODE} AS OFFICE_CODE, #{row.LOGINUSER_COMP_CODE} AS COMP_CODE, #{row.USER_ID} AS USER_ID, COALESCE(NULLIF(#{row.PASSWD1}, ''), RIGHT(CONVERT(varchar, #{row.HP_NO}), 4), '1234') AS PASSWD, #{row.USER_NAME} AS USER_NAME, #{row.REGI_DATE} AS REGI_DATE, #{row.USE_YN} AS USE_YN, #{row.HP_NO} AS HP_NO, #{row.STATUS} AS STATUS, #{row.REG_END_DATE} AS REG_END_DATE, #{row.DEPT_CD} AS DEPT_CD, #{row.JOB_DUTY_CD} AS JOB_DUTY_CD, #{row.ID_GBN} AS ID_GBN, #{row.REMARK} AS REMARK, #{row.EMP_NO} AS EMP_NO, #{row.GROUP_DTL_CD} AS GROUP_DTL_CD, #{row.EMAIL} AS EMAIL
) AS U ON A.USER_ID = U.USER_ID AND A.OFFICE_CODE = U.OFFICE_CODE AND ISNULL(A.COMP_CODE, '') = ISNULL(U.COMP_CODE, '')

UPDATE A SET A.FORM_USE = U.FORM_USE, A.GRD_CREATE = U.GRD_CREATE, A.GRD_READ = U.GRD_READ, A.GRD_UPDATE = U.GRD_UPDATE, A.GRD_DELETE = U.GRD_DELETE, A.GRD_EXCEL = U.GRD_EXCEL FROM dbo.TPM_USERMENU A JOIN(
SELECT #{row.MENU_ID} AS MENU_ID, #{row.USER_ID} AS USER_ID, #{row.FORM_USE} AS FORM_USE, #{row.GRD_CREATE} AS GRD_CREATE, #{row.GRD_READ} AS GRD_READ, #{row.GRD_UPDATE} AS GRD_UPDATE, #{row.GRD_DELETE} AS GRD_DELETE, #{row.GRD_EXCEL} AS GRD_EXCEL
) AS U ON A.MENU_ID = U.MENU_ID AND A.USER_ID = U.USER_ID

UPDATE A SET A.MGMCOMP_NAME = U.MGMCOMP_NAME, A.NUM = U.NUM, A.CEO = U.CEO, A.CEO_HP = U.CEO_HP, A.CON = U.CON, A.ITEM = U.ITEM, A.ZIP = U.ZIP, A.ADDR1 = U.ADDR1, A.ADDR2 = U.ADDR2, A.TEL = U.TEL, A.FAX = U.FAX, A.EMAIL = U.EMAIL, A.HOMEPAGE = U.HOMEPAGE, A.REGI_DAY = U.REGI_DAY, A.OFF_DAY = U.OFF_DAY, A.STATE = U.STATE, A.USE_YN = U.USE_YN FROM dbo.TPM_MGM_COMPANY A JOIN(
SELECT #{row.MGMCOMP_CODE} AS MGMCOMP_CODE, #{row.MGMCOMP_NAME} AS MGMCOMP_NAME, #{row.NUM} AS NUM, #{row.CEO} AS CEO, #{row.CEO_HP} AS CEO_HP, #{row.CON} AS CON, #{row.ITEM} AS ITEM, #{row.ZIP} AS ZIP, #{row.ADDR1} AS ADDR1, #{row.ADDR2} AS ADDR2, #{row.TEL} AS TEL, #{row.FAX} AS FAX, #{row.EMAIL} AS EMAIL, #{row.HOMEPAGE} AS HOMEPAGE, #{row.REGI_DAY} AS REGI_DAY, #{row.OFF_DAY} AS OFF_DAY, #{row.STATE} AS STATE, #{row.USE_YN} AS USE_YN
) AS U ON A.MGMCOMP_CODE = U.MGMCOMP_CODE

UPDATE A SET A.COMP_NAME = U.COMP_NAME, A.NUM = U.NUM, A.CEO = U.CEO, A.CEO_HP = U.CEO_HP, A.CON = U.CON, A.ITEM = U.ITEM, A.ZIP = U.ZIP, A.ADDR1 = U.ADDR1, A.ADDR2 = U.ADDR2, A.TEL = U.TEL, A.FAX = U.FAX, A.EMAIL = U.EMAIL, A.HOMEPAGE = U.HOMEPAGE, A.REGI_DAY = U.REGI_DAY, A.OFF_DAY = U.OFF_DAY, A.STATE = U.STATE, A.USE_YN = U.USE_YN, A.MGMUSER_ID = U.MGMUSER_ID, A.GROUP_CODE = U.GROUP_CODE FROM dbo.TPM_COMPANY A JOIN(
SELECT #{row.COMP_CODE} AS COMP_CODE, #{row.COMP_NAME} AS COMP_NAME, #{row.NUM} AS NUM, #{row.CEO} AS CEO, #{row.CEO_HP} AS CEO_HP, #{row.CON} AS CON, #{row.ITEM} AS ITEM, #{row.ZIP} AS ZIP, #{row.ADDR1} AS ADDR1, #{row.ADDR2} AS ADDR2, #{row.TEL} AS TEL, #{row.FAX} AS FAX, #{row.EMAIL} AS EMAIL, #{row.HOMEPAGE} AS HOMEPAGE, #{row.REGI_DAY} AS REGI_DAY, #{row.OFF_DAY} AS OFF_DAY, #{row.STATE} AS STATE, #{row.USE_YN} AS USE_YN, #{row.MGMUSER_ID} AS MGMUSER_ID, #{row.GROUP_CODE} AS GROUP_CODE
) AS U ON A.COMP_CODE = U.COMP_CODE

