SELECT A.COMP_CODE, A.MGMUSER_ID FROM dbo.TPM_COMPANY A WHERE A.STATE = '107001'
AND A.COMP_CODE = #{COMP_CODE}
ORDER BY A.MGMUSER_ID

WITH LatestContract AS ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY OFFICE_CODE ORDER BY START_DATE DESC, CONT_SEQ DESC ) AS RN FROM dbo.TPM_CONTRACT ), LatestContract2 AS ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY OFFICE_CODE ORDER BY PLAN_MONTH DESC, SEQ DESC ) AS RN FROM dbo.TRP_MONTH_REPAIR_BASIC ) SELECT A.OFFICE_CODE, A.OFFICE_NAME, ISNULL(A.COMP_CODE, '') AS COMP_CODE, A.MGMCOMP_CODE AS MGMCOMP_CODE, A.EXPLAN, A.PART1, A.PART2, A.TEL, A.FAX, A.ZIP, A.ADDR1, A.ADDR2, A.MAGOR_NAME, A.MAJOR_HP, A.REGI_DAY, ISNULL(A.STATUS, '104003') AS STATUS, dbo.getCode_nm(A.STATUS) as STATUS_NM, A.MGMUSER_ID, A.OFFICE_HARD_SIZE, A.OFFICE_USER_CNT, A.OFFICE_CNT, A.OFFICE_AREAR, A.START_DAY, A.END_DAY, B.CONT_SEQ, B.START_DATE, B.END_DATE, B.CONT_KIND_CD, dbo.getCode_nm(B.CONT_KIND_CD) as CONT_KIND_NM, B.CONT_AMT, C.PLAN_GBN, dbo.getCode_nm(C.PLAN_GBN) as PLAN_GBN_NM, C.PLAN_MONTH, C.STATUS AS REPAIR_STATUS, dbo.getCode_nm(C.STATUS) as REPAIR_STATUS_NM FROM dbo.TPM_OFFICE A LEFT JOIN LatestContract B ON A.OFFICE_CODE = B.OFFICE_CODE AND B.RN = 1 LEFT JOIN LatestContract2 C ON A.OFFICE_CODE = C.OFFICE_CODE AND C.RN = 1 WHERE A.STATUS LIKE '%' + #{STATUS} + '%'
AND B.CONT_KIND_CD LIKE '%' + #{CONT_KIND_CD} + '%'
AND END_DATE >= #{END_DATE1}
AND END_DATE <= #{END_DATE2}
AND A.MGMCOMP_CODE = #{LOGINUSER_MGMCOMP_CODE}
AND A.COMP_CODE = #{LOGINUSER_COMP_CODE}
ORDER BY A.OFFICE_CODE, A.REGI_DAY, B.START_DATE

