UPDATE A SET A.OFFICE_NAME = U.OFFICE_NAME, A.COMP_CODE = U.COMP_CODE, A.EXPLAN = U.EXPLAN, A.PART1 = U.PART1, A.PART2 = U.PART2, A.TEL = U.TEL, A.FAX = U.FAX, A.ZIP = U.ZIP, A.ADDR1 = U.ADDR1, A.ADDR2 = U.ADDR2, A.MAGOR_NAME = U.MAGOR_NAME, A.MAJOR_HP = U.MAJOR_HP, A.REGI_DAY = U.REGI_DAY, A.STATUS = U.STATUS, A.MGMUSER_ID = U.MGMUSER_ID, A.OFFICE_HARD_SIZE = U.OFFICE_HARD_SIZE, A.OFFICE_USER_CNT = U.OFFICE_USER_CNT, A.OFFICE_CNT = U.OFFICE_CNT, A.OFFICE_AREAR = U.OFFICE_AREAR, A.START_DAY = U.START_DAY, A.END_DAY = U.END_DAY FROM dbo.TPM_OFFICE A JOIN(
SELECT #{row.OFFICE_CODE} AS OFFICE_CODE, #{row.OFFICE_NAME} AS OFFICE_NAME, #{row.COMP_CODE} AS COMP_CODE, #{row.EXPLAN} AS EXPLAN, #{row.PART1} AS PART1, #{row.PART2} AS PART2, #{row.TEL} AS TEL, #{row.FAX} AS FAX, #{row.ZIP} AS ZIP, #{row.ADDR1} AS ADDR1, #{row.ADDR2} AS ADDR2, #{row.MAGOR_NAME} AS MAGOR_NAME, #{row.MAJOR_HP} AS MAJOR_HP, #{row.REGI_DAY} AS REGI_DAY, #{row.STATUS} AS STATUS, #{row.MGMUSER_ID} AS MGMUSER_ID, #{row.OFFICE_HARD_SIZE} AS OFFICE_HARD_SIZE, #{row.OFFICE_USER_CNT} AS OFFICE_USER_CNT, #{row.OFFICE_CNT} AS OFFICE_CNT, #{row.OFFICE_AREAR} AS OFFICE_AREAR, #{row.START_DAY} AS START_DAY, #{row.END_DAY} AS END_DAY
) AS U ON A.OFFICE_CODE = U.OFFICE_CODE

UPDATE A SET A.CONTRACT_NO = U.CONTRACT_NO, A.START_DATE = U.START_DATE, A.END_DATE = U.END_DATE, A.CONT_KIND_CD = U.CONT_KIND_CD, A.CONT_AMT = U.CONT_AMT, A.REV_DATE = U.REV_DATE, A.REV_REASON = U.REV_REASON, A.REMARKS = U.REMARKS FROM dbo.TPM_CONTRACT A JOIN(
SELECT #{row.OFFICE_CODE} AS OFFICE_CODE, #{row.CONT_SEQ} AS CONT_SEQ, #{row.CONTRACT_NO} AS CONTRACT_NO, #{row.START_DATE} AS START_DATE, #{row.END_DATE} AS END_DATE, #{row.CONT_KIND_CD} AS CONT_KIND_CD, #{row.CONT_AMT} AS CONT_AMT, #{row.REV_DATE} AS REV_DATE, #{row.REV_REASON} AS REV_REASON, #{row.REMARKS} AS REMARKS
) AS U ON A.OFFICE_CODE = U.OFFICE_CODE AND A.CONT_SEQ = U.CONT_SEQ

mapper.select:
WITH LatestContract AS ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY OFFICE_CODE ORDER BY START_DATE DESC, CONT_SEQ DESC ) AS RN FROM dbo.TPM_CONTRACT ), LatestContract2 AS ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY OFFICE_CODE ORDER BY PLAN_MONTH DESC, SEQ DESC ) AS RN FROM dbo.TRP_MONTH_REPAIR_BASIC ) SELECT A.OFFICE_CODE, A.OFFICE_NAME, A.PART1, A.PART2, ISNULL(A.COMP_CODE, '') AS COMP_CODE, ISNULL(A.MGMCOMP_CODE, '') AS MGMCOMP_CODE, A.EXPLAN, A.PART1, dbo.getCode_nm(A.PART1) as PART1_NM, A.PART2, dbo.getCode_nm(A.PART2) as PART2_NM, A.TEL, A.FAX, '(' + A.ZIP + ') ' + A.ADDR1 + ' ' + A.ADDR2 AS ADDR, A.MAGOR_NAME, A.MAJOR_HP, D.COMP_NAME, A.MGMUSER_ID, A.REGI_DAY, ISNULL(A.STATUS, '104003') AS STATUS, dbo.getCode_nm(A.STATUS) as STATUS_NM, A.OFFICE_HARD_SIZE, A.OFFICE_USER_CNT, A.OFFICE_CNT, A.OFFICE_AREAR, B.CONT_SEQ, B.START_DATE, B.END_DATE, B.CONT_KIND_CD, dbo.getCode_nm(B.CONT_KIND_CD) as CONT_KIND_NM, B.CONT_AMT, B.REV_DATE, B.REV_REASON, C.PLAN_GBN, dbo.getCode_nm(C.PLAN_GBN) as PLAN_GBN_NM, C.PLAN_MONTH, C.STATUS AS REPAIR_STATUS, dbo.getCode_nm(C.STATUS) as REPAIR_STATUS_NM FROM dbo.TPM_OFFICE A LEFT JOIN LatestContract B ON A.OFFICE_CODE = B.OFFICE_CODE AND B.RN = 1 LEFT JOIN LatestContract2 C ON A.OFFICE_CODE = C.OFFICE_CODE AND C.RN = 1 LEFT JOIN TPM_COMPANY D ON A.COMP_CODE = D.COMP_CODE WHERE A.STATUS LIKE '%' + #{STATUS} + '%'
AND B.CONT_KIND_CD LIKE '%' + #{CONT_KIND_CD} + '%'
AND A.MGMCOMP_CODE = #{LOGINUSER_MGMCOMP_CODE}
AND A.COMP_CODE = #{LOGINUSER_COMP_CODE}
ORDER BY A.OFFICE_CODE, A.REGI_DAY, B.START_DATE

