UPDATE dbo.TPM_BOARD
SET BOARD_CNT = ISNULL(BOARD_CNT, 0) + 1
WHERE BOARD_DIV = #{BOARD_DIV} AND BOARD_NO = #{BOARD_NO}

UPDATE dbo.TPM_BOARD
SET
	BOARD_TITLE   =  #{BOARD_TITLE},
	BOARD_CONTENT =  #{BOARD_CONTENT}
WHERE BOARD_DIV = #{BOARD_DIV} AND BOARD_NO = #{BOARD_NO}

