SELECT #{row.USERGROUP_ID} AS USERGROUP_ID, #{row.MENU_ID} AS MENU_ID, #{row.FORM_USE} AS FORM_USE, #{row.GRD_CREATE} AS GRD_CREATE, #{row.GRD_READ} AS GRD_READ, #{row.GRD_UPDATE} AS GRD_UPDATE, #{row.GRD_DELETE} AS GRD_DELETE, #{row.GRD_EXCEL} AS GRD_EXCEL
) AS B ON A.MENU_ID = B.MENU_ID

UPDATE A SET A.MENU_ID = B.MENU_ID, A.FORM_USE = B.FORM_USE, A.GRD_CREATE = B.GRD_CREATE, A.GRD_READ = B.GRD_READ, A.GRD_UPDATE = B.GRD_UPDATE, A.GRD_DELETE = B.GRD_DELETE, A.GRD_EXCEL = B.GRD_EXCEL FROM dbo.TPM_GROUPMENU AS A JOIN(
SELECT #{row.USERGROUP_ID} AS USERGROUP_ID, #{row.MENU_ID} AS MENU_ID, #{row.FORM_USE} AS FORM_USE, #{row.GRD_CREATE} AS GRD_CREATE, #{row.GRD_READ} AS GRD_READ, #{row.GRD_UPDATE} AS GRD_UPDATE, #{row.GRD_DELETE} AS GRD_DELETE, #{row.GRD_EXCEL} AS GRD_EXCEL
) AS B ON A.MENU_ID = B.MENU_ID

UPDATE A SET A.CODEDV_NM = B.CODEDV_NM, A.USE_YN = B.USE_YN FROM dbo.TPM_CODE_MST AS A JOIN(
SELECT #{row.CODEDV_NO} AS CODEDV_NO, #{row.CODEDV_NM} AS CODEDV_NM, #{row.USE_YN} AS USE_YN
) AS B ON A.CODEDV_NO = B.CODEDV_NO

UPDATE A SET A.CODEDTL_NM = B.CODEDTL_NM, A.SHORT_NM = B.SHORT_NM, A.DIVISION1_NM = B.DIVISION1_NM, A.DIVISION2_NM = B.DIVISION2_NM, A.DIVISION3_NM = B.DIVISION3_NM, A.DIVISION4_NM = B.DIVISION4_NM, A.DIVISION5_NM = B.DIVISION5_NM, A.SORTORDER = B.SORTORDER, A.USE_YN = B.USE_YN FROM dbo.TPM_CODEBODY AS A JOIN(
SELECT #{row.CODEDV_NO} AS CODEDV_NO, #{row.CODE_NO} AS CODE_NO, #{row.CODEDTL_NM} AS CODEDTL_NM, #{row.SHORT_NM} AS SHORT_NM, #{row.DIVISION1_NM} AS DIVISION1_NM, #{row.DIVISION2_NM} AS DIVISION2_NM, #{row.DIVISION3_NM} AS DIVISION3_NM, #{row.DIVISION4_NM} AS DIVISION4_NM, #{row.DIVISION5_NM} AS DIVISION5_NM, #{row.SORTORDER} AS SORTORDER, #{row.USE_YN} AS USE_YN
) AS B ON A.CODEDV_NO = B.CODEDV_NO AND A.CODE_NO = B.CODE_NO
